SELECT am.CSNAME AS `股票名称`, am.COMB_SYMBOL AS `股票代码`, vc.F001D AS `财政周期结束日期`, vc.F005V AS `货币`, vc.F006V AS `业务板块名称`, ROUND(vc.F007N/100000000, 3) AS `营业收入（亿）`, ROUND(vc.F007N / NULLIF(SUM(vc.F007N) OVER (PARTITION BY am.COMB_SYMBOL, vc.F001D), 0) * 100, 2) AS `收入占比(%)` FROM AMERICAN_STOCK_MAIN am LEFT JOIN VIEW_COM3105 vc ON am.FIU_ID = vc.FIU_ID WHERE am.COMB_SYMBOL = 'GOOGL.US' AND vc.F001D >= '2024-07-01' AND vc.F001D <= '2025-06-30' AND vc.F007N IS NOT NULL AND vc.F006V IS NOT NULL ORDER BY vc.F001D DESC, `收入占比(%)` DESC;
